package com.veltronixnexus.nativeengine;
import android.media.*;import android.net.Uri;import androidx.media3.common.*;import androidx.media3.transformer.*;import androidx.work.*;import com.getcapacitor.*;import com.getcapacitor.annotation.CapacitorPlugin;import java.io.File;import java.nio.ByteBuffer;import java.util.UUID;import java.util.concurrent.atomic.AtomicBoolean;
@CapacitorPlugin(name="NexusNativeEngine")
public class NexusNativeEnginePlugin extends Plugin {
 private Transformer transformer; private final AtomicBoolean busy=new AtomicBoolean(false);
 @PluginMethod public void extractAudio(PluginCall call){
  String src=call.getString("sourceUri");if(src==null){call.reject("Source URI required");return;}MediaExtractor ex=new MediaExtractor();MediaMuxer mux=null;
  try{Uri uri=Uri.parse(src);if("content".equals(uri.getScheme()))ex.setDataSource(getContext(),uri,null);else ex.setDataSource(uri.getPath());int track=-1;for(int i=0;i<ex.getTrackCount();i++){String m=ex.getTrackFormat(i).getString(MediaFormat.KEY_MIME);if(m!=null&&m.startsWith("audio/")){track=i;break;}}if(track<0){call.reject("No audio track in source video");return;}ex.selectTrack(track);File out=new File(getContext().getCacheDir(),"nexus-audio-"+System.currentTimeMillis()+".m4a");mux=new MediaMuxer(out.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int dest=mux.addTrack(ex.getTrackFormat(track));mux.start();long from=(long)(Math.max(0,call.getDouble("startSeconds",0.0))*1e6),to=(long)(call.getDouble("endSeconds",-1.0)*1e6);ex.seekTo(from,MediaExtractor.SEEK_TO_CLOSEST_SYNC);ByteBuffer b=ByteBuffer.allocateDirect(1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long base=-1;while(true){b.clear();int n=ex.readSampleData(b,0);if(n<0)break;long pts=ex.getSampleTime();if(to>0&&pts>to)break;if(base<0)base=pts;info.set(0,n,Math.max(0,pts-base),ex.getSampleFlags());mux.writeSampleData(dest,b,info);if(!ex.advance())break;}mux.stop();mux.release();mux=null;ex.release();JSObject o=new JSObject();o.put("fileUri",Uri.fromFile(out).toString());o.put("fileName",out.getName());o.put("mimeType","audio/mp4");call.resolve(o);
  }catch(Exception e){if(mux!=null){try{mux.stop();}catch(Exception ignored){}mux.release();}try{ex.release();}catch(Exception ignored){}call.reject("MediaExtractor audio extraction failed: "+e.getMessage(),e);}
 }
 @PluginMethod public void transcodeVideo(PluginCall call){if(!busy.compareAndSet(false,true)){call.reject("Native export already running");return;}String src=call.getString("sourceUri");if(src==null){busy.set(false);call.reject("Source URI required");return;}File out=new File(getContext().getCacheDir(),"nexus-media3-"+System.currentTimeMillis()+".mp4");try{Transformer.Listener l=new Transformer.Listener(){@Override public void onCompleted(Composition c,ExportResult r){busy.set(false);transformer=null;JSObject o=new JSObject();o.put("fileUri",Uri.fromFile(out).toString());o.put("fileName",out.getName());o.put("mimeType","video/mp4");call.resolve(o);}@Override public void onError(Composition c,ExportResult r,ExportException e){busy.set(false);transformer=null;call.reject("Media3 video transcode failed: "+e.getMessage(),e);}};transformer=new Transformer.Builder(getContext()).setVideoMimeType(MimeTypes.VIDEO_H264).setAudioMimeType(MimeTypes.AUDIO_AAC).addListener(l).build();transformer.start(new EditedMediaItem.Builder(MediaItem.fromUri(Uri.parse(src))).build(),out.getAbsolutePath());}catch(Exception e){busy.set(false);transformer=null;call.reject("Could not start Media3 transcode: "+e.getMessage(),e);}}
 @PluginMethod public void cancelNativeExport(PluginCall c){if(transformer!=null){transformer.cancel();transformer=null;}busy.set(false);c.resolve();}
 @PluginMethod public void enqueueBackgroundCopy(PluginCall c){String src=c.getString("sourceUri");if(src==null){c.reject("Source URI required");return;}Data d=new Data.Builder().putString("sourceUri",src).putString("outputName",c.getString("outputName","nexus-export")).build();OneTimeWorkRequest w=new OneTimeWorkRequest.Builder(BackgroundMediaCopyWorker.class).setInputData(d).build();WorkManager.getInstance(getContext()).enqueue(w);JSObject o=new JSObject();o.put("jobId",w.getId().toString());c.resolve(o);}
 @PluginMethod public void getBackgroundCopyStatus(PluginCall c){String id=c.getString("jobId");try{WorkInfo w=WorkManager.getInstance(getContext()).getWorkInfoById(UUID.fromString(id)).get();if(w==null){c.reject("Job not found");return;}JSObject o=new JSObject();o.put("state",w.getState().name());o.put("progress",w.getProgress().getInt("progress",0));String uri=w.getOutputData().getString("fileUri"),err=w.getOutputData().getString("error");if(uri!=null)o.put("fileUri",uri);if(err!=null)o.put("error",err);c.resolve(o);}catch(Exception e){c.reject("Could not read background task",e);}}
}